BOSS=dict(th="เคสใหญ่: เศร้ามาสองเดือน",en="Boss case: Two months of low mood",
case="A 34-year-old woman has 2 months of low mood, anhedonia, early waking, poor appetite and difficulty concentrating. No psychotic features, no history of mania. She wants to avoid weight gain and sexual side effects if possible.",
qs=[
("First-line drug class for major depressive disorder:",["SSRIs","MAO inhibitors","Tricyclics","Benzodiazepines"],0,"Best tolerability and safety in overdose."),
("How long before an antidepressant's full mood effect?",["4–8 weeks","1 day","1 week only","6 months"],0,"Side effects come before benefit."),
("Which antidepressant has the least sexual dysfunction and no weight gain?",["Bupropion","Paroxetine","Mirtazapine","Sertraline"],0,"NE/DA reuptake inhibitor; lowers seizure threshold."),
("Before starting an antidepressant, screen for bipolar disorder because:",["Antidepressant monotherapy may trigger mania","SSRIs lower the seizure threshold markedly","Bipolar patients need higher SSRI doses","Bipolar disorder changes SSRI metabolism"],0,"Ask about past manic episodes."),
("Serotonin syndrome may occur if an SSRI is combined with:",["MAOIs, linezolid or tramadol","Acetaminophen or ibuprofen","Metformin or glipizide","Amoxicillin or cephalexin"],0,"Hyperthermia, clonus, agitation; cyproheptadine treats it. Triptans, St John’s wort and other serotonergic drugs also add risk."),
("When switching from fluoxetine to an MAOI, wait:",["5 weeks","2 days","1 week","No washout"],0,"Fluoxetine has a long half-life (norfluoxetine)."),
],pass_=4)
